113:     fun build(): CallPlan {
114:         val sinks = sinks()
115:         val (callees, models, unresolved) = resolve()
116:         val zeroCanReturn = unresolved || callees.isNotEmpty() || models.any { it.second.zeroCanReturn }
117:         val back = bindBack()
118:         val stages = buildList {
119:             add(Edges(BEFORE, BOUND, BIND_IN, bindIn()))
120:             for (sink in sinks) if (sink.endFacts.isNotEmpty())
121:                 add(Edges(BOUND, REWRITTEN, END_FACTS, MicroEdgeBuilder().apply {
122:                     sink.endFacts.forEach { edge(it.edge) }
123:                 }.buildStage(), Guard.SinkTriggered(sink)))
124:             add(Edges(BOUND, REWRITTEN, SOURCES, sources(sinks, zeroCanReturn)))
125:             add(Actions(BOUND, ADDED, cleanSteps()))
126:             if (callees.isNotEmpty()) add(Callees(ADDED, RETURNED, callees))
127:             for ((target, model) in models) add(Predefined(ADDED, RETURNED, target, model, model.compile(manager)))
128:             if (unresolved) {
129:                 add(Edges(ADDED, RETURNED, UNRESOLVED, StatementSummary.identities(boundPositions())))
130:                 add(Edges(ADDED, RETURNED, UNRESOLVED, passRules()))
131:             }
132:             if (callee.isConstructor && models.none { it.first === callee })
133:                 add(Edges(ADDED, REWRITTEN, CONSTRUCTOR, StatementSummary.identities(boundPositions())))
134:             val rewriterSteps = rewriterSteps()
135:             add(if (forms.isRun1GroupView) Actions.run1GroupReturnRewriter(rewriterSteps, manager.marks)
136:                 else Actions.run1FullReturnRewriter(rewriterSteps, manager.marks))
137:             add(Edges(REWRITTEN, AFTER, BIND_BACK, back))
138:             aliases(back)?.let { add(Edges(REWRITTEN, AFTER, ALIASES, it, Guard.MemoryEffect)) }

