241:     private fun TracePathNode.unwrapBoundary(previous: TracePathNode?): TracePathNode {
242:         val statement = statement
243:         if (statement !is JMethodBoundaryInst) return this
244: 
245:         val instructions = statement.location.method.instList.instructions
246:         val previousStatement = previous?.statement?.takeIf { it.location.method == statement.location.method }
247:         val real = when (statement) {
248:             is JMethodEnterInst -> instructions.first()
249:             is JMethodExitNormalInst -> previousStatement as? JIRReturnInst
250:                 ?: instructions.lastOrNull { it is JIRReturnInst }
251:             is JMethodExitExceptionalInst -> previousStatement as? JIRThrowInst
252:                 ?: instructions.lastOrNull { it is JIRThrowInst }
253:         } ?: return this
